from pathlib import Path

ROOT = Path("FushERP_Mobile_Phase5")

gradle = ROOT / 'app/build.gradle.kts'
text = gradle.read_text(encoding='utf-8')
text = text.replace('versionCode = 16', 'versionCode = 17')
text = text.replace('versionName = "0.12.2-phase12-fk-hotfix"', 'versionName = "0.12.3-phase12-recipes"')
assert 'versionCode = 17' in text and '0.12.3-phase12-recipes' in text
gradle.write_text(text, encoding='utf-8')

service = ROOT / 'app/src/main/java/com/fush/erp/domain/ProductionService.kt'
text = service.read_text(encoding='utf-8')
marker = '''    data class CostSummary(\n        val materialCostBase: Double,\n        val laborCostBase: Double,\n        val totalCostBase: Double,\n        val acceptedQtyBase: Double,\n        val unitCostBase: Double\n    )\n\n\n'''
insert = marker + '''    data class RecipeComponentInput(\n        val itemId: Long,\n        val quantityBase: Double,\n        val stage: String = "PREPARATION",\n        val expectedLossPct: Double = 0.0\n    )\n\n    suspend fun createRecipe(\n        productItemId: Long,\n        targetOutputQtyBase: Double,\n        components: List<RecipeComponentInput>,\n        notes: String = ""\n    ): Long = db.withTransaction {\n        require(targetOutputQtyBase > 0.0 && targetOutputQtyBase.isFinite()) { "الناتج القياسي يجب أن يكون أكبر من صفر" }\n        val product = requireNotNull(db.itemDao().byId(productItemId)) { "المنتج النهائي غير موجود" }\n        require(product.isActive && product.category == "FINISHED_GOOD") { "يجب اختيار منتج نهائي فعال" }\n        require(db.recipeDao().activeForProduct(productItemId) == null) { "يوجد بالفعل إصدار فعال لهذا المنتج؛ استخدم إنشاء إصدار جديد" }\n        require(components.isNotEmpty()) { "يجب إضافة مكون واحد على الأقل للوصفة" }\n        require(components.map { it.itemId }.distinct().size == components.size) { "لا يمكن تكرار المكون نفسه داخل الوصفة" }\n        components.forEach { component ->\n            require(component.itemId != productItemId) { "لا يمكن استخدام المنتج النهائي كمكون لنفسه" }\n            val item = requireNotNull(db.itemDao().byId(component.itemId)) { "أحد مكونات الوصفة غير موجود" }\n            require(item.isActive && item.category != "FINISHED_GOOD") { "مكونات الوصفة يجب أن تكون مواد خام أو مواد تغليف فعالة" }\n            require(component.quantityBase > 0.0 && component.quantityBase.isFinite()) { "كمية مكون الوصفة غير صالحة" }\n            require(component.expectedLossPct in 0.0..100.0 && component.expectedLossPct.isFinite()) { "نسبة الفاقد غير صالحة" }\n            require(component.stage in setOf("PREPARATION", "MIXING", "FILLING")) { "مرحلة مكون الوصفة غير صالحة" }\n        }\n\n        val code = "BOM-" + product.code.removePrefix("FG-")\n        val versionNo = db.recipeDao().maxVersion(code) + 1\n        val now = System.currentTimeMillis()\n        val recipeId = db.recipeDao().insertRecipe(\n            RecipeEntity(\n                code = code,\n                productItemId = product.id,\n                versionNo = versionNo,\n                effectiveFrom = now,\n                targetOutputQtyBase = targetOutputQtyBase,\n                status = "ACTIVE",\n                notes = notes,\n                createdAt = now\n            )\n        )\n        db.recipeDao().insertComponents(\n            components.mapIndexed { index, component ->\n                RecipeComponentEntity(\n                    recipeId = recipeId,\n                    itemId = component.itemId,\n                    quantityBase = component.quantityBase,\n                    expectedLossPct = component.expectedLossPct,\n                    stage = component.stage,\n                    sequenceNo = index + 1\n                )\n            }\n        )\n        recipeId\n    }\n\n\n'''
if marker not in text:
    raise SystemExit('CostSummary marker not found')
text = text.replace(marker, insert, 1)
service.write_text(text, encoding='utf-8')

screen = ROOT / 'app/src/main/java/com/fush/erp/ui/screens/ProductionScreens.kt'
text = screen.read_text(encoding='utf-8')
text = text.replace(
'''    val employees by container.db.employeeDao().observeActiveEmployees().collectAsState(initial = emptyList())\n    var showNewOrder by remember { mutableStateOf(false) }\n''',
'''    val employees by container.db.employeeDao().observeActiveEmployees().collectAsState(initial = emptyList())\n    val allItems by container.db.itemDao().observeAll().collectAsState(initial = emptyList())\n    var showNewRecipe by remember { mutableStateOf(false) }\n    var showNewOrder by remember { mutableStateOf(false) }\n''', 1)
text = text.replace(
'''            Button(onClick = { showNewOrder = true }, enabled = recipes.isNotEmpty()) { Text("أمر إنتاج جديد") }\n            message?.let { Text(it, color = MaterialTheme.colorScheme.primary) }\n''',
'''            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                Button(onClick = { showNewOrder = true }, enabled = recipes.any { it.status == "ACTIVE" }) { Text("أمر إنتاج جديد") }\n                OutlinedButton(onClick = { showNewRecipe = true }) { Text("وصفة جديدة") }\n            }\n            message?.let { Text(it, color = MaterialTheme.colorScheme.primary) }\n''', 1)
insert_before = '''    if (showNewOrder) {\n'''
new_block = '''    if (showNewRecipe) {\n        NewRecipeDialog(\n            finishedProducts = allItems.filter { it.category == "FINISHED_GOOD" && it.isActive },\n            componentItems = allItems.filter { it.category != "FINISHED_GOOD" && it.isActive },\n            onDismiss = { showNewRecipe = false }\n        ) { product, outputQty, components, notes ->\n            scope.launch {\n                try {\n                    val id = container.productionService.createRecipe(\n                        productItemId = product.id,\n                        targetOutputQtyBase = outputQty,\n                        components = components.map {\n                            com.fush.erp.domain.ProductionService.RecipeComponentInput(\n                                itemId = it.item.id,\n                                quantityBase = it.quantityBase,\n                                stage = it.stage\n                            )\n                        },\n                        notes = notes\n                    )\n                    message = "تم إنشاء الوصفة رقم $id للمنتج ${product.nameAr}"\n                    showNewRecipe = false\n                } catch (e: Exception) {\n                    message = e.message ?: "تعذر إنشاء الوصفة"\n                }\n            }\n        }\n    }\n\n'''
if insert_before not in text:
    raise SystemExit('showNewOrder marker not found')
text = text.replace(insert_before, new_block + insert_before, 1)

func_marker = '''@Composable\nprivate fun RecipeVersionDialog(\n'''
dialog_code = '''private data class NewRecipeComponentDraft(\n    val item: ItemEntity,\n    val quantityBase: Double,\n    val stage: String\n)\n\n@Composable\nprivate fun NewRecipeDialog(\n    finishedProducts: List<ItemEntity>,\n    componentItems: List<ItemEntity>,\n    onDismiss: () -> Unit,\n    onSave: (ItemEntity, Double, List<NewRecipeComponentDraft>, String) -> Unit\n) {\n    var product by remember { mutableStateOf<ItemEntity?>(null) }\n    var outputText by remember { mutableStateOf("") }\n    var componentItem by remember { mutableStateOf<ItemEntity?>(null) }\n    var componentQtyText by remember { mutableStateOf("") }\n    var componentStage by remember { mutableStateOf("PREPARATION") }\n    var notes by remember { mutableStateOf("") }\n    var localMessage by remember { mutableStateOf<String?>(null) }\n    val components = remember { mutableStateListOf<NewRecipeComponentDraft>() }\n\n    fun stageAr(stage: String): String = when (stage) {\n        "PREPARATION" -> "التحضير"\n        "MIXING" -> "الخلط"\n        "FILLING" -> "التعبئة"\n        else -> stage\n    }\n\n    AlertDialog(\n        onDismissRequest = onDismiss,\n        title = { Text("وصفة جديدة") },\n        text = {\n            LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.heightIn(max = 560.dp)) {\n                item {\n                    if (finishedProducts.isEmpty()) {\n                        Text("لا يوجد منتج نهائي. أضف المنتج أولًا من القائمة ← البيانات ← المواد والأصناف.", color = MaterialTheme.colorScheme.error)\n                    } else {\n                        SelectionField("المنتج النهائي", product?.nameAr ?: "اختر", finishedProducts, { "${it.nameAr} (${it.code})" }) { product = it }\n                    }\n                    OutlinedTextField(\n                        value = outputText,\n                        onValueChange = { outputText = it },\n                        label = { Text("الناتج القياسي بالوحدة الأساسية") },\n                        singleLine = true\n                    )\n                    Text("أضف مكونات الخلطة واحدًا واحدًا", style = MaterialTheme.typography.titleSmall)\n                    SelectionField("المكون", componentItem?.nameAr ?: "اختر", componentItems, { "${it.nameAr} (${it.code})" }) { componentItem = it }\n                    OutlinedTextField(\n                        value = componentQtyText,\n                        onValueChange = { componentQtyText = it },\n                        label = { Text("كمية المكون") },\n                        singleLine = true\n                    )\n                    StringSelectionField(\n                        "المرحلة",\n                        stageAr(componentStage),\n                        listOf("PREPARATION", "MIXING", "FILLING")\n                    ) { componentStage = it }\n                    OutlinedButton(\n                        onClick = {\n                            val item = componentItem\n                            val qty = componentQtyText.toDoubleOrNull()\n                            when {\n                                item == null -> localMessage = "اختر المكون"\n                                qty == null || qty <= 0.0 -> localMessage = "أدخل كمية صحيحة للمكون"\n                                components.any { it.item.id == item.id } -> localMessage = "هذا المكون مضاف بالفعل"\n                                else -> {\n                                    components.add(NewRecipeComponentDraft(item, qty, componentStage))\n                                    componentItem = null\n                                    componentQtyText = ""\n                                    localMessage = null\n                                }\n                            }\n                        },\n                        enabled = componentItems.isNotEmpty()\n                    ) { Text("إضافة المكون") }\n                    localMessage?.let { Text(it, color = MaterialTheme.colorScheme.error) }\n                    HorizontalDivider()\n                    Text("المكونات (${components.size})", style = MaterialTheme.typography.titleSmall)\n                }\n                items(components, key = { it.item.id }) { component ->\n                    ElevatedCard(Modifier.fillMaxWidth()) {\n                        Row(Modifier.fillMaxWidth().padding(8.dp), horizontalArrangement = Arrangement.SpaceBetween) {\n                            Column(Modifier.weight(1f)) {\n                                Text(component.item.nameAr)\n                                Text("${formatProductionQty(component.quantityBase)} ${stageAr(component.stage)}")\n                            }\n                            TextButton(onClick = { components.remove(component) }) { Text("حذف") }\n                        }\n                    }\n                }\n                item {\n                    OutlinedTextField(notes, { notes = it }, label = { Text("ملاحظات الوصفة") })\n                }\n            }\n        },\n        confirmButton = {\n            Button(\n                enabled = product != null && outputText.toDoubleOrNull()?.let { it > 0 } == true && components.isNotEmpty(),\n                onClick = { onSave(product!!, outputText.toDouble(), components.toList(), notes) }\n            ) { Text("حفظ الوصفة") }\n        },\n        dismissButton = { TextButton(onClick = onDismiss) { Text("إلغاء") } }\n    )\n}\n\n@Composable\nprivate fun RecipeVersionDialog(\n'''
if func_marker not in text:
    raise SystemExit('RecipeVersionDialog marker not found')
text = text.replace(func_marker, dialog_code, 1)
screen.write_text(text, encoding='utf-8')

home = ROOT / 'app/src/main/java/com/fush/erp/ui/screens/HomeShell.kt'
text = home.read_text(encoding='utf-8')
text = text.replace('Metric("الإصدار", "0.12.2", Modifier.weight(1f))', 'Metric("الإصدار", "0.12.3", Modifier.weight(1f))')
home.write_text(text, encoding='utf-8')

(ROOT / 'PHASE12_3_SCOPE.md').write_text('''# Phase 12.3 — Full Recipe Management\n\n- Create a brand-new BOM for any active finished-good item.\n- Automatic BOM code derived from the finished-good code.\n- Standard output quantity.\n- Add multiple raw/packaging components with quantity and stage.\n- Prevent duplicate components and duplicate active recipe for one product.\n- Existing recipe versioning remains immutable/versioned.\n- No database schema change; update preserves all existing data.\n''', encoding='utf-8')

assert 'OutlinedButton(onClick = { showNewRecipe = true }) { Text("وصفة جديدة") }' in screen.read_text(encoding='utf-8')
assert 'suspend fun createRecipe(' in service.read_text(encoding='utf-8')
print('PHASE12_3_RECIPES_PATCH_APPLIED')
